pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address _baseToken, address _nft) public {
        // The rule: after `initialize`, `nft()` must return the `_nft` argument.
        vm.assume(_baseToken != _nft); // otherwise the bug is indistinguishable
        c.initialize(
            _baseToken,
            _nft,
            1,   // _virtualBaseTokenReserves (nonzero to pass potential zero checks)
            1,   // _virtualNftReserves
            0,   // _changeFee
            0,   // _feeRate
            bytes32(0), // _merkleRoot
            false, // _useStolenNftOracle
            false  // _payRoyalties
        );
        assertTrue(c.nft() == _nft);
    }
}

